35	float t[3];
36	inline
37	void mapForward(float x, float y, float &u, float &v)
38	{
39		//cout << "r_kinv: "<< r_kinv[0] << endl;
40		//cout << "r_kinv: "<< r_kinv[3] << endl;
41		//cout << "r_kinv: "<< r_kinv[6] << endl;
42		float x_ = r_kinv[0] * x + r_kinv[1] * y + r_kinv[2];
43		float y_ = r_kinv[3] * x + r_kinv[4] * y + r_kinv[5];
44		float z_ = r_kinv[6] * x + r_kinv[7] * y + r_kinv[8];
45	
46		u = scale * atan2f(x_, z_);
47		v = scale * y_ / sqrtf(x_ * x_ + z_ * z_);
48	
49	}
50	inline
51	void mapBackward(float u, float v, float &x, float &y)
52	{
53		u /= scale;
54		v /= scale;
55	
56		float x_ = sinf(u);
57		float y_ = v;
58		float z_ = cosf(u);
59	
60		float z;
61		x = k_rinv[0] * x_ + k_rinv[1] * y_ + k_rinv[2] * z_;
62		y = k_rinv[3] * x_ + k_rinv[4] * y_ + k_rinv[5] * z_;
63		z = k_rinv[6] * x_ + k_rinv[7] * y_ + k_rinv[8] * z_;
64	
65		if (z > 0) { x /= z; y /= z; }
66		else x = y = -1;
67	}
68	void detectResultRoi(Size src_size, Point &dst_tl, Point &dst_br)
69	{
70		float tl_uf = (std::numeric_limits<float>::max)();
71		float tl_vf = (std::numeric_limits<float>::max)();
72		float br_uf = -(std::numeric_limits<float>::max)();
73		float br_vf = -(std::numeric_limits<float>::max)();
74	
75		float u, v;
76		for (int y = 0; y < src_size.height; ++y)
77		{
78			for (int x = 0; x < src_size.width; ++x)
79			{
80	
81				mapForward(static_cast<float>(x), static_cast<float>(y), u, v);
82				tl_uf = (std::min)(tl_uf, u); tl_vf = (std::min)(tl_vf, v);
83				br_uf = (std::max)(br_uf, u); br_vf = (std::max)(br_vf, v);
84			}
85		}
86	
87		dst_tl.x = static_cast<int>(tl_uf);
88		dst_tl.y = static_cast<int>(tl_vf);
89		dst_br.x = static_cast<int>(br_uf);
90		dst_br.y = static_cast<int>(br_vf);
91	}
92	
93	void setCameraParams(InputArray _K, InputArray _R, InputArray _T = Mat::zeros(3, 1, CV_32F))
94	{
95		Mat K = _K.getMat(), R = _R.getMat(), T = _T.getMat();
96	
97		CV_Assert(K.size() == Size(3, 3) && K.type() == CV_32F);
98		CV_Assert(R.size() == Size(3, 3) && R.type() == CV_32F);
99		CV_Assert((T.size() == Size(1, 3) || T.size() == Size(3, 1)) && T.type() == CV_32F);
100	
101		Mat_<float> K_(K);
102		k[0] = K_(0, 0); k[1] = K_(0, 1); k[2] = K_(0, 2);
103		k[3] = K_(1, 0); k[4] = K_(1, 1); k[5] = K_(1, 2);
104		k[6] = K_(2, 0); k[7] = K_(2, 1); k[8] = K_(2, 2);
105	
106		Mat_<float> Rinv = R.t();
107		rinv[0] = Rinv(0, 0); rinv[1] = Rinv(0, 1); rinv[2] = Rinv(0, 2);
108		rinv[3] = Rinv(1, 0); rinv[4] = Rinv(1, 1); rinv[5] = Rinv(1, 2);
109		rinv[6] = Rinv(2, 0); rinv[7] = Rinv(2, 1); rinv[8] = Rinv(2, 2);
110	
111		Mat_<float> R_Kinv = R * K.inv();
112		r_kinv[0] = R_Kinv(0, 0); r_kinv[1] = R_Kinv(0, 1); r_kinv[2] = R_Kinv(0, 2);
113		r_kinv[3] = R_Kinv(1, 0); r_kinv[4] = R_Kinv(1, 1); r_kinv[5] = R_Kinv(1, 2);
114		r_kinv[6] = R_Kinv(2, 0); r_kinv[7] = R_Kinv(2, 1); r_kinv[8] = R_Kinv(2, 2);
115	
116		Mat_<float> K_Rinv = K * Rinv;
117		k_rinv[0] = K_Rinv(0, 0); k_rinv[1] = K_Rinv(0, 1); k_rinv[2] = K_Rinv(0, 2);
118		k_rinv[3] = K_Rinv(1, 0); k_rinv[4] = K_Rinv(1, 1); k_rinv[5] = K_Rinv(1, 2);
119		k_rinv[6] = K_Rinv(2, 0); k_rinv[7] = K_Rinv(2, 1); k_rinv[8] = K_Rinv(2, 2);
120	
121		Mat_<float> T_(T.reshape(0, 3));
122		t[0] = T_(0, 0); t[1] = T_(1, 0); t[2] = T_(2, 0);
123	}
124	
125	Rect buildMaps(Size src_size, InputArray K, InputArray R, OutputArray _xmap, OutputArray _ymap)
126	{
127		setCameraParams(K, R);
128		Point dst_tl, dst_br;
129		detectResultRoi(src_size, dst_tl, dst_br);
130	
131		_xmap.create(dst_br.y - dst_tl.y + 1, dst_br.x - dst_tl.x + 1, CV_32F);
132		_ymap.create(dst_br.y - dst_tl.y + 1, dst_br.x - dst_tl.x + 1, CV_32F);
133	
134		Mat xmap = _xmap.getMat(), ymap = _ymap.getMat();
135		float x, y;
136		for (int v = dst_tl.y; v <= dst_br.y; ++v)
137		{
138			for (int u = dst_tl.x; u <= dst_br.x; ++u)
139			{
140				mapBackward(static_cast<float>(u), static_cast<float>(v), x, y);
141				xmap.at<float>(v - dst_tl.y, u - dst_tl.x) = x;
142				ymap.at<float>(v - dst_tl.y, u - dst_tl.x) = y;
143			}
144		}
145	
146		return Rect(dst_tl, dst_br);
147	}
